// НЕ ПРОВЕРЕН В ЖИВОМ БРАУЗЕРЕ: сессия браузера генератора была вошедшей (user1), гостевые маршруты не открывались.
import { test, expect } from '@playwright/test';

test.use({ viewport: { width: 390, height: 844 } });

const routes: { url: string; title: RegExp }[] = [
  { url: '/', title: /אור הגאולה/ },
  { url: '/phone', title: /^כניסה דרך מספר נייד · אור הגאולה$/ },
  { url: '/register', title: /אור הגאולה/ },
];

test.describe('Web-оболочка — гость', () => {
  test('WS-01 На каждом гостевом маршруте document.title не пустой и есть favicon #6a8edf78 @prod-safe @mobile', async ({ page }) => {
    // 1. По очереди открыть `/`, `/phone`, `/register`; после загрузки прочитать `document.title` и `link[rel*=icon]`.
    for (const r of routes) {
      await test.step(r.url, async () => {
        await page.goto(r.url);
        await expect(page).toHaveTitle(r.title);
        const icons = page.locator('link[rel*=icon]');
        expect(await icons.count()).toBeGreaterThan(0);
        for (const href of await icons.evaluateAll((els) => els.map((e) => e.getAttribute('href')))) {
          expect(href).toBe('/favicon.ico');
        }
      });
    }
  });
});
